/// Current text revision, derived from the one append-only catalog.
/// 当前文本修订号，从唯一追加式目录派生。
pub const HOST_MESSAGE_GUIDANCE_VERSION: usize = HOST_MESSAGE_GUIDANCE_REVISIONS.len();

/// Current fixed host guidance for newly initialized baselines.
/// 新初始化基线使用的当前固定宿主指引。
pub const HOST_MESSAGE_GUIDANCE: &str =
    HOST_MESSAGE_GUIDANCE_REVISIONS[HOST_MESSAGE_GUIDANCE_VERSION - 1];

/// Returns the exact registered revision of `text`, or None for unknown or edited content.
/// 返回 `text` 精确匹配的已登记修订；未知或被改写正文返回 None。
pub fn host_message_guidance_version(text: &str) -> Option<usize> {
    HOST_MESSAGE_GUIDANCE_REVISIONS
        .iter()
        .position(|known| *known == text)
        .map(|index| index + 1)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Every immutable text resolves uniquely; forged and whitespace-edited text is rejected.
    /// 每份不可变正文唯一解析；伪造或空白改写后的正文被拒绝。
    #[test]
    fn host_guidance_revisions_are_exact_and_unique() {
        for (index, text) in HOST_MESSAGE_GUIDANCE_REVISIONS.iter().enumerate() {
            assert_eq!(host_message_guidance_version(text), Some(index + 1));
            assert_eq!(host_message_guidance_version(&format!("{text} ")), None);
        }
        assert_eq!(host_message_guidance_version("unregistered guidance"), None);
        assert_eq!(
            host_message_guidance_version(HOST_MESSAGE_GUIDANCE),
            Some(HOST_MESSAGE_GUIDANCE_VERSION)
        );
    }
}
